  ["ad098965ed2332c6"] = { "Tu avere troppa paura! Me trova te!", "." },
  ["ad12bd7fa863f8aa"] = { "Finalmente!! Posso lasciare questo letamaio.", "." },
  ["ad1444e02cd9f785"] = { "Che la leggenda di Stalvan riposi!", "." },
  ["ad1445f809e89df3"] = { "Eh? Che vuoi?", "." },
  ["ad194abe6b8a7366"] = { "Proprio mentre parliamo, {class}, tutto il materiale bellico viene trasportato a ⟦Silithus=Silitus⟧. A quanto pare, l'ultimo carico dovrebbe arrivare in meno di un giorno. Dopodiché, servirà che qualche <eroe/eroina> venga a suonare il gong all'Altare dello Scarabeo. Allora la guerra comincerà davvero.", "." },
  ["ad1a2725a60d534e"] = { "Ho perso il mio ⟦Signet of the Unseen Path=Sigillo del Sentiero Invisibile⟧. Puoi sostituirmelo?", "." },
  ["ad1bda5f2572dab2"] = { "Ricorda: se svengo di nuovo, l'acqua che ti ha dato Spraggle mi farà rinvenire.", "." },
  ["ad1cd4947a7c59a5"] = { "%s si dissolve nell'etere, ma i suoi venti ululanti ti risuonano ancora nelle orecchie.", "." },
  ["ad1f19bac6e62e83"] = { "Valstann, desideroso di compiacere il padre, convinse Fandral a lasciargli guidare un piccolo battaglione in difesa di ⟦Southwind Village=Vento del Sud⟧. Con le sorti della battaglia ormai a loro favore, di certo nessun male poteva capitare al suo amato figlio. Nessuno si accorse della trappola. Valstann fu catturato dai Qiraji in agguato e il villaggio di ⟦Southwind Village=Vento del Sud⟧ fu cancellato. Rajaxx in persona avrebbe condotto il prigioniero Valstann in prima linea dove, davanti a Staghelm e alle forze degli elfi della notte, avrebbe giustiziato brutalmente il giovane elfo della notte.", "." },
  ["ad1ffec0b33c8c5d"] = { "Oh no! Eccoli che arrivano!", "." },
  ["ad21939bd7f7a937"] = { "Si è passato il limite. Come osa il Flagello attaccare ⟦Stormwind=Roccavento⟧! Distruggetelo prima che ne arrivino altri!", "." },
  ["ad23de3ae0e85669"] = { "Un po' di questo unguento dovrebbe aiutare.", "." },
  ["ad27884eaee63868"] = { "Abbiamo abbastanza rifornimenti per lanciare un assalto di terra. Se vuoi consegnare gli ordini, e pensi di averne i requisiti, parla con il caporale Noreg Stormpike.", "." },
  ["ad2c0b7559c888c9"] = { "I segreti nascosti nei piloni del ⟦Un'Goro Crater=Cratere di Un'Goro⟧ ora sono tuoi. Visita i piloni quando vuoi per accedere al loro potere e ottenere risorse utili.", "." },
  ["ad2d267589334d3d"] = { "Cos'hai lì? Fammi dare un'occhiata...", "." },
  ["ad38c4126310d77b"] = { "Se il dovere non mi legasse a mastro Ravenholdt, ti seguirei fino ai confini del mondo, <signore/signora> {name}. Sei la grazia e l'astuzia fatte persona.", "." },
  ["ad3da6eabea486f3"] = { "Salve, <cittadino/cittadina>. Hai l'aria di <un/una> <uomo/donna> con uno scopo: hai affari con l'esercito di ⟦Stormwind=Roccavento⟧?", "." },
  ["ad3e07dc3b83c840"] = { "Be', <ragazzo/ragazza>, trovi Shelby Stoneflint proprio fuori dalla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧, a Kharanos. Si prenderà cura di qualsiasi famiglio tu abbia.", "." },
  ["ad435cc2aac8a15c"] = { "%s abbandona il blocco che teneva fermo sulla soglia e guarda verso l'esca.", "." },
  ["ad47805b3ee1306e"] = { "%s entra in trance...", "." },
  ["ad4c630b4f4b3ba9"] = { "Allora, vediamo se ho capito bene. Stavi nuotando, anzi, facendo il dorso nella lava fusa con questa... questa tua tuta da lava? Sì? E dal nulla questa bestia ti ha inghiottito in un boccone?", "." },
  ["ad581cb551408dc9"] = { "%s scompare nel bosco.", "." },
  ["ad60d6f06b8c8b31"] = { "Battaglia! Sento l'odore della tua paura, {class}!", "." },
  ["ad6697463be099b7"] = { "Il mio signore andrà su tutte le furie quando saprà di questa imboscata. Speriamo che la tua morte lo plachi.", "." },
  ["ad67ddf2ecd2f4ce"] = { "SE dicono... SE! Non ci sono se che tengano su ⟦Ironforge=Forgiardente⟧! Eh? E adesso che c'è?", "." },
  ["ad747b4d4ce04abc"] = { "Salve, {name}. Qui addestro e accudisco i giovani ippogrifi; dai pure un'occhiata in giro.", "." },
  ["ad7cbe81c57cf144"] = { "Throm'ka, {class}! Sei <pronto/pronta> a combattere per l'⟦Horde=Orda⟧ nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧?", "." },
  ["ad7fb10887617a41"] = { "Tieni a bada i nemici e intanto riducili a cotolette. L'unico problema è che l'asta lunga mi impedisce di sporcarmi le mani di sangue.", "." },
  ["ad8d83edaf7a89e9"] = { "Bleah... nemmeno se fossi l'ultimo orco di Kalimdor, Lunk.", "." },
  ["ad960d7777e510f7"] = { "La Stormpike Aid Station è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ la conquisterà!", "." },
  ["ad9c55216a09cf80"] = { "%s striscia nervosamente fuori dalla cassa.", "." },
  ["ad9c79fe77499851"] = { "Abbiamo raccolto molti rifornimenti per la ricostruzione, ma ce ne servono ancora parecchi per riparare Dun Baldar. Continua a portarmi rifornimenti!", "." },
  ["ad9fb8c642409dfb"] = { "Questo atto di follia non resterà impunito!", "." },
  ["ada710129f79ea70"] = { "Difendete la barricata!", "." },
  ["ada78182e829b1f5"] = { "Posso avere un altro Dawn's Gambit, Betina? Voglio provarlo di nuovo...", "." },
  ["adb0a9eaa24f67f2"] = { "Le maree della guerra sono tornate. Dal gelido nord, le necropoli del Re dei Lich hanno posto sotto assedio le nostre terre. Lui e il suo maledetto generale, Kel'Thuzad, mandano necropoli volanti a invadere il mondo intero.", "." },
  ["adb1f64243f1d7e9"] = { "Ben detto!", "." },
  ["adb2489bd7642bbb"] = { "%s salta dalla prima catapulta alla seconda!", "." },
  ["adb35c010871a4ba"] = { "Vanndar Stormpike è il generale dell'esercito dell'⟦Alliance=Alleanza⟧ ad Alterac e guida le sue forze da Dun Baldar.\n\nSe verrà sconfitto, l'⟦Alliance=Alleanza⟧ perderà di sicuro la battaglia per Alterac.\n\nAl momento Vanndar non si trova nella ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["adb781452801659a"] = { "Il ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧ è scavato nelle montagne, oltre il ponte a est di Dun Baldar.\n\nAl momento è controllato dall'⟦Horde=Orda⟧.", "." },
  ["adb7d7d82343f5cc"] = { "Ysida è viva grazie al tuo coraggio, {name}. Ho un grande debito con te e ti aiuterò per quanto è in mio potere.", "." },
  ["adc334ce030b1853"] = { "Oh, <un/una> <sacerdote/sacerdotessa>, eh? Be', il buon vecchio Maxan lo trovi di sicuro a farsi un goccio alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧, se ti serve un po' d'addestramento.", "." },
  ["addc214cf7e9734d"] = { "Il mondo è in debito con te e con i tuoi alleati, {name}.", "." },
  ["addf19af9e685dd9"] = { "<Mio/Mia> <signore/signora>, ti prego, lasciami vivere abbastanza da vederti purificare questo mondo dagli infedeli.", "." },
  ["ade1f912304b0272"] = { "Da qui ce la faccio. Grazie, {name}! E parla con il mio datore di lavoro per una ricompensa!", "." },
  ["ade8b02363f59e3c"] = { "Dammi uno dei tuoi oggetti magici.", "." },
  ["adec48ed53a8abd7"] = { "Una piastrella scivolosa ti fa perdere l'equilibrio.", "." },
  ["adf45c92d9ba3ba3"] = { "Questi boschi un tempo meravigliosi soffrono sotto una terribile maledizione! Forze corruttrici deformano la vita di questo luogo in ombre di ciò che era. Se non sei un agente di questa corruzione, forse puoi aiutarmi a riconquistare ⟦Felwood=Vilbosco⟧!", "." },
  ["adf8b400a3dc7c2a"] = { "Direi di sì!", "." },
})
